			cur.Meta.Subject = strings.TrimPrefix(line, "summary ")
			continue
		}
	}

	if err := scanner.Err(); err != nil {
		return nil, err
	}
	if cur != nil {
		if cur.LineText == "" {
			return nil, fmt.Errorf("truncated blame record for commit %s at line %d", cur.Hash, cur.EndLine)
		}
		if err := flush(); err != nil {
			return nil, err
		}
	}

	return blocks, nil
}

type whyBlameHeader struct {
	Hash     string
	EndLine  int
	Meta     whyCommitInfo
	LineText string
}

func shortCommitHash(hash string) string {
	if len(hash) <= 10 {
		return hash
	}
	return hash[:10]
}

func isHexCommitHash(hash string) bool {
	if len(hash) == 0 {
		return false
	}
	for _, r := range hash {
		switch {
		case r >= '0' && r <= '9':
		case r >= 'a' && r <= 'f':
		case r >= 'A' && r <= 'F':
		default:
			return false
		}
	}
	return true
}

