		"author Stefan Haubold",
		"summary Improve CLI error handling",
		"\tvar silent *cli.SilentError",
	}, "\n")

	blocks, err := parseWhyBlamePorcelain(strings.NewReader(input))
	if err != nil {
		t.Fatalf("parse error: %v", err)
	}
	if len(blocks) != 2 {
		t.Fatalf("block count = %d, want 2", len(blocks))
	}
	if got, want := blocks[0].StartLine, 23; got != want {
		t.Fatalf("first start line = %d, want %d", got, want)
	}
	if got, want := blocks[0].EndLine, 24; got != want {
		t.Fatalf("first end line = %d, want %d", got, want)
	}
	if got, want := len(blocks[0].CodeLines), 2; got != want {
		t.Fatalf("first code line count = %d, want %d", got, want)
	}
	if got, want := blocks[0].CodeLines[0], "if runtime.GOOS != \"windows\" {"; got != want {
		t.Fatalf("first code line[0] = %q, want %q", got, want)
	}
	if got, want := blocks[0].CodeLines[1], "\tsignals = append(signals, syscall.SIGTERM)"; got != want {
		t.Fatalf("first code line[1] = %q, want %q", got, want)
	}
	if got, want := blocks[0].Commit.Subject, "Handle interrupt signals"; got != want {
		t.Fatalf("first subject = %q, want %q", got, want)
	}
	if got, want := blocks[1].StartLine, 38; got != want {
		t.Fatalf("second start line = %d, want %d", got, want)
	}
	if got, want := blocks[1].EndLine, 38; got != want {
		t.Fatalf("second end line = %d, want %d", got, want)
	}
	if got, want := blocks[1].Commit.Subject, "Improve CLI error handling"; got != want {
		t.Fatalf("second subject = %q, want %q", got, want)
	}
}

func TestParseWhyBlame_TruncatedRecordReturnsError(t *testing.T) {
	t.Parallel()

	input := strings.Join([]string{
		"7f93a963e3222222222222222222222222222222 38 38 1",
		"author Stefan Haubold",
		"summary Improve CLI error handling",
	}, "\n")

	_, err := parseWhyBlamePorcelain(strings.NewReader(input))
	if err == nil {
		t.Fatal("expected parse error")
	}
	if got, want := err.Error(), "truncated blame record"; !strings.Contains(got, want) {
		t.Fatalf("error = %q, want substring %q", got, want)
	}
}

func TestLoadWhyBlocks_UsesBlameRunner(t *testing.T) {
	orig := runGitBlamePorcelain
	t.Cleanup(func() { runGitBlamePorcelain = orig })

	const wantPath = "cmd/entire/main.go"

	runGitBlamePorcelain = func(_ context.Context, path string) (string, error) {
		if path != wantPath {
			t.Fatalf("path = %q, want %q", path, wantPath)
		}
		return "7f93a963e3222222222222222222222222222222 1 1 1\nauthor Stefan Haubold\nsummary boot\n\tpackage main\n", nil
	}

	blocks, err := loadWhyBlocks(context.Background(), wantPath)
	if err != nil {
		t.Fatalf("load error: %v", err)
	}
	if len(blocks) != 1 {
		t.Fatalf("block count = %d, want 1", len(blocks))
	}
	if got, want := blocks[0].Commit.Subject, "boot"; got != want {
		t.Fatalf("subject = %q, want %q", got, want)
	}
	if got, want := blocks[0].CodeLines, []string{"package main"}; len(got) != len(want) || got[0] != want[0] {
		t.Fatalf("code lines = %#v, want %#v", got, want)
	}
}

